// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // We are the owner (since deployed from this contract, msg.sender = address(this))
        // Set address(0x123) as an approved logger
        address logger = address(0x123);
        c.setApprovedLogger(logger, true);
        // Now call approvedToLog with logger
        bool result = c.approvedToLog(logger);
        // The reference returns true (because logger is approved), the bug returns false
        assertTrue(result);
    }
}

