// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // First, approve the contract itself as a logger (to mimic the test caller)
        vm.prank(address(c)); // onlyOwner is address(c), since no owner was set - but we can't call setApprovedLogger safely
        // Actually, the owner is the deployer (this contract). So we can call setApprovedLogger.
        c.setApprovedLogger(address(this), true);

        // Now call logRegisteredPubkey as an approved logger
        bool result = c.logRegisteredPubkey(keccak256("x"), keccak256("y"));

        // The reference C: if (approvedToLog(msg.sender)) return false; -> approved is true -> returns false
        // The bug M: if (approvedToLog(msg.sender)) return false; -> approved is true -> returns false (same in this case? Wait, need to check the change: the bug changes the condition to always true, i.e., removes the negation. Let me re-evaluate)
        // Actually the change is: from "if (!approvedToLog(msg.sender)) return false;" to "if (approvedToLog(msg.sender)) return false;"
        // So for an approved logger: reference has !true = false, so no return false, emits event, returns true.
        // Bug has true = true, so it returns false without emitting.
        // So the reference returns true, the bug returns false.
        assertTrue(result == true, "Reference should return true");
    }
}

