        // Use a separate owner to approve the logger
        vm.prank(address(this)); // deployer is owner by default
        c.setApprovedLogger(logger, true);

        // Call logCourtesyCalled as the approved logger
        vm.prank(logger);
        bool success = c.logCourtesyCalled();

        // Assert that the call returned true (both versions do this)
        assertTrue(success);

        // The key difference: reference emits an event, mutant does not.
        // We can verify this by checking that exactly one log with the event's signature was emitted.
        // The event signature hash for CourtesyCalled(address,uint256) is:
        // keccak256("CourtesyCalled(address,uint256)")
        bytes32 eventSignature = keccak256("CourtesyCalled(address,uint256)");
        // The reference should have emitted this event, so there should be at least one log with this topic.
        // The mutant emits no event, so there should be zero such logs.
        // We use vm.getRecordedLogs() after the call to check.
        // However, we need to record logs first.
        // Simpler approach: check the number of logs emitted.
        // Since we know the reference emits exactly one event (CourtesyCalled) and the mutant emits none,
