        // We'll use vm.record() and vm.getRecordedLogs() to count logs.
        // Actually, let's just check if the event was emitted by looking at the logs.
        vm.record();
        vm.prank(logger);
        c.logCourtesyCalled();
        Vm.Log[] memory entries = vm.getRecordedLogs();
        // The reference should have exactly 1 log entry (the emitted event)
        // The mutant should have 0 log entries
        // We assert that the number of logs is exactly 1 for the reference
        // (This will fail on the mutant because it emits no logs)
        assertEq(entries.length, 1, "Should emit exactly one event (CourtesyCalled)");
        // Additionally, check the first topic matches the event signature
